const M = window.MANIFEST;
const $ = (s, el = document) => el.querySelector(s);
const esc = s => s.replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const project = id => PROJECTS.find(x => x.id === id);

const totals = {
  projects: PROJECTS.length,
  images: PROJECTS.filter(p => !p.video).reduce((n, p) => n + M[p.id].length, 0),
  reels: M.reels.length,
  frames: M.stopmotion.length,
};

// glass folder icon, used on both pages
function folderIcon(p) {
  const items = M[p.id];
  const [a, b] = p.video ? [M.khanqah[0], M.field[3]] : [items[0], items[1] || items[0]];
  return `
    <span class="f-icon">
      <span class="f-back"></span>
      <span class="f-paper p1" style="background-image:url('${a.thumb}')"></span>
      <span class="f-paper p2" style="background-image:url('${b.thumb}')"></span>
      <span class="f-front"><span class="f-tag">${esc(p.tag)}</span><span class="f-count">${items.length} ${p.video ? 'clips' : 'files'}</span></span>
    </span>`;
}

// ── folder window ──
const win = $('#win'), grid = $('#winGrid'), flipBtn = $('#flipBtn'), flipbook = $('#flipbook');
let current = null, flipTimer = null, lastFocus = null;

function openWindow(id) {
  const p = project(id);
  current = p;
  lastFocus = document.activeElement;
  $('#winTitle').textContent = p.title;
  $('#winDesc').textContent = p.desc;
  $('#winPath').textContent = `~/rollnumberninee/my-works/${p.id}`;
  grid.innerHTML = M[id].map((it, i) => p.video
    ? `<button class="tile" data-i="${i}"><video src="${it.src}#t=0.5" muted playsinline preload="metadata"></video></button>`
    : `<button class="tile" data-i="${i}"><img src="${it.thumb}" width="${it.w}" height="${it.h}" loading="lazy" alt="${esc(p.title)} — ${i + 1}"></button>`
  ).join('');
  flipBtn.hidden = !p.flipbook;
  stopFlip();
  win.hidden = false;
  document.body.style.overflow = 'hidden';
  $('[data-close]', win).focus();
}
function closeWindow() {
  stopFlip();
  win.hidden = true;
  grid.innerHTML = '';
  document.body.style.overflow = '';
  lastFocus && lastFocus.focus();
}
grid.addEventListener('click', e => {
  const t = e.target.closest('.tile');
  if (t) openLightbox(M[current.id], +t.dataset.i, current.title, !!current.video);
});
win.addEventListener('click', e => { if (e.target === win || e.target.closest('[data-close]')) closeWindow(); });

function stopFlip() {
  clearInterval(flipTimer); flipTimer = null;
  flipbook.hidden = true;
  flipBtn.textContent = '▶ Play flipbook';
}
flipBtn.addEventListener('click', () => {
  if (flipTimer) return stopFlip();
  const frames = M.stopmotion, img = $('img', flipbook);
  frames.forEach(f => { new Image().src = f.src; });   // warm the cache
  let i = 0;
  img.src = frames[0].src;
  flipbook.hidden = false;
  flipBtn.textContent = '■ Stop';
  flipTimer = setInterval(() => { i = (i + 1) % frames.length; img.src = frames[i].src; }, 160);
});

// ── lightbox ──
const lb = $('#lb'), lbMedia = $('#lbMedia'), lbCap = $('#lbCap');
let lbList = [], lbIdx = 0, lbTitle = '', lbVideo = false;

function openLightbox(list, i, title, isVideo) {
  lbList = list; lbIdx = i; lbTitle = title; lbVideo = isVideo;
  lb.hidden = false;
  document.body.style.overflow = 'hidden';
  renderLb();
  $('.lb-close', lb).focus();
}
function renderLb() {
  const it = lbList[lbIdx];
  lbMedia.innerHTML = lbVideo
    ? `<video src="${it.src}" controls autoplay playsinline></video>`
    : `<img src="${it.src}" alt="${esc(lbTitle)} — ${lbIdx + 1}">`;
  lbCap.textContent = `${lbTitle} · ${lbIdx + 1} / ${lbList.length}`;
}
function stepLb(d) { lbIdx = (lbIdx + d + lbList.length) % lbList.length; renderLb(); }
function closeLb() {
  lb.hidden = true; lbMedia.innerHTML = '';
  document.body.style.overflow = win.hidden ? '' : 'hidden';
}
$('.lb-prev', lb).addEventListener('click', () => stepLb(-1));
$('.lb-next', lb).addEventListener('click', () => stepLb(1));
lb.addEventListener('click', e => { if (e.target === lb || e.target.closest('[data-close]')) closeLb(); });

// ── search: filters the desktop on My Works, jumps to My Works from the landing page ──
const q = $('#q'), desktop = $('#desktop');
const worksURL = term => 'works.html' + (term ? `?q=${encodeURIComponent(term)}` : '');
if (q && !desktop) {
  $('#search').addEventListener('submit', e => { e.preventDefault(); location.href = worksURL(q.value.trim()); });
}

document.addEventListener('keydown', e => {
  if (!lb.hidden) {
    if (e.key === 'Escape') closeLb();
    if (e.key === 'ArrowLeft') stepLb(-1);
    if (e.key === 'ArrowRight') stepLb(1);
  } else if (!win.hidden && e.key === 'Escape') closeWindow();
  else if (q && win.hidden && e.key === '/' && document.activeElement !== q) { e.preventDefault(); q.focus(); }
});

// ── My Works: desktop, filter chips, dock ──
if (desktop) {
  desktop.innerHTML = PROJECTS.map((p, i) => `
    <button class="folder" data-id="${p.id}" style="animation-delay:${i * 50}ms">
      ${folderIcon(p)}
      <span class="f-label"><strong>${esc(p.title)}</strong><span>${esc(p.sub)}</span></span>
    </button>`).join('');
  desktop.addEventListener('click', e => {
    const f = e.target.closest('.folder');
    if (f) openWindow(f.dataset.id);
  });

  const empty = $('#empty'), state = $('#filterState'), count = $('#deskCount'), chips = $('#chips');
  function applyFilter(term, { push = true } = {}) {
    const t = term.trim().toLowerCase();
    let shown = 0;
    desktop.querySelectorAll('.folder').forEach(el => {
      const p = project(el.dataset.id);
      const hay = `${p.title} ${p.sub} ${p.tag} ${p.tags}`.toLowerCase();
      const ok = !t || t.split(/\s+/).every(w => hay.includes(w));
      el.hidden = !ok;
      el.classList.toggle('hit', ok && !!t);
      shown += ok;
    });
    empty.hidden = shown > 0;
    state.hidden = !t;
    if (t) state.innerHTML = `Showing ${shown} folder${shown === 1 ? '' : 's'} for “${esc(t)}” <button type="button" id="clearF">clear</button>`;
    count.textContent = `${shown} item${shown === 1 ? '' : 's'}`;
    chips.querySelectorAll('.chip').forEach(c => c.setAttribute('aria-pressed', c.dataset.q === t));
    if (push) history.replaceState(null, '', worksURL(t));
  }
  q.addEventListener('input', () => applyFilter(q.value));
  $('#search').addEventListener('submit', e => { e.preventDefault(); applyFilter(q.value); $('#desk').scrollIntoView(); });
  state.addEventListener('click', e => { if (e.target.id === 'clearF') { q.value = ''; applyFilter(''); } });
  chips.addEventListener('click', e => {
    const c = e.target.closest('.chip');
    if (!c) return;
    q.value = c.dataset.q;
    applyFilter(q.value);
  });
  q.value = new URLSearchParams(location.search).get('q') || '';
  applyFilter(q.value, { push: false });

  // second ring: the same folders, empty, turning the opposite way
  const emptySet = $('#emptySet');
  if (emptySet) {
    emptySet.innerHTML = PROJECTS.map(() => `
      <div class="folder folder-empty">
        <span class="f-icon"><span class="f-back"></span><span class="f-front"></span></span>
      </div>`).join('');
  }

  const orbit = $('#orbit');
  if (orbit) runOrbit(orbit, desktop, 1);
  if (emptySet) runOrbit($('#orbit2'), emptySet, -1);

  // dock: a mini cover per folder, magnifies on hover
  const dock = $('#dock');
  dock.innerHTML = PROJECTS.map(p => {
    const cover = p.video ? M.field[3] : M[p.id][0];
    return `<button class="dock-item" data-id="${p.id}" aria-label="Open ${esc(p.title)}"><img src="${cover.thumb}" alt=""><span class="dock-tip mono">${esc(p.title)}</span></button>`;
  }).join('') + `<i class="dock-sep"></i><a class="dock-item dock-home" href="index.html" aria-label="Home"><span>9</span><span class="dock-tip mono">Home</span></a>`;
  dock.addEventListener('click', e => {
    const d = e.target.closest('button.dock-item');
    if (d) openWindow(d.dataset.id);
  });
  const items = [...dock.querySelectorAll('.dock-item')];
  dock.addEventListener('mousemove', e => {
    items.forEach(it => {
      const r = it.getBoundingClientRect();
      const dist = Math.abs(e.clientX - (r.left + r.width / 2));
      it.style.setProperty('--mag', (1 + Math.max(0, 1 - dist / 140) * .55).toFixed(3));
    });
  });
  dock.addEventListener('mouseleave', () => items.forEach(it => it.style.setProperty('--mag', 1)));

  // open a folder straight from a link, e.g. works.html#khanqah
  const fromHash = location.hash.slice(1);
  if (project(fromHash)) openWindow(fromHash);
}

// folders orbit on a 3D ellipse at a constant speed; hovering one eases the ring to a stop.
// dir: 1 = clockwise, -1 = counter-clockwise
function runOrbit(orbit, set, dir) {
  {
    const LAP = 45;                                   // seconds per revolution
    let angle = 0, speed = 1, target = 1, held = null, last = performance.now();
    set.querySelectorAll('.folder').forEach(el => {
      const hold = () => { held = el; target = 0; };
      const release = () => { if (held === el) held = null; target = held ? 0 : 1; };
      el.addEventListener('mouseenter', hold);
      el.addEventListener('mouseleave', release);
      el.addEventListener('focus', hold);
      el.addEventListener('blur', release);
    });
    const frame = now => {
      const dt = Math.min(.05, (now - last) / 1000); last = now;
      speed += (target - speed) * Math.min(1, dt * 5);      // ease in/out of the stop
      angle += dir * speed * dt * Math.PI * 2 / LAP;
      const els = [...set.querySelectorAll('.folder:not([hidden])')];
      const n = els.length, W = orbit.clientWidth, H = orbit.clientHeight;
      const narrow = W < 640;
      const fw = narrow ? 112 : W < 1000 ? 170 : 210;
      // phones get a taller, narrower ellipse so nine folders still have room
      const rx = narrow ? W * .34 : Math.min(W * .42 - fw * .25, 600);
      const ry = narrow ? H * .3 : Math.min(H * .27, rx * .4);
      orbit.style.setProperty('--fw', fw + 'px');
      orbit.style.setProperty('--rx', rx.toFixed(0));
      orbit.style.setProperty('--ry', ry.toFixed(0));
      orbit.style.setProperty('--track-dy', (fw * .3).toFixed(0));
      els.forEach((el, i) => {
        const a = n === 1 ? Math.PI / 2 : angle + i * Math.PI * 2 / n;
        const z = Math.sin(a), d = (z + 1) / 2;              // d: 0 at the back, 1 at the front
        const x = Math.cos(a) * rx, y = z * ry;
        const s = .5 + .5 * d;
        el.style.transform = `translate(-50%, -50%) translate3d(${x.toFixed(1)}px, ${y.toFixed(1)}px, 0) scale(${s.toFixed(3)})`;
        el.style.zIndex = el === held ? 200 : Math.round(d * 100);
        el.style.opacity = el === held ? 1 : (.32 + .68 * d).toFixed(2);
        el.classList.toggle('is-back', d < .45 && el !== held);
      });
      requestAnimationFrame(frame);
    };
    requestAnimationFrame(frame);
  }
}

